// Lookup returns the glyph for r. If r is not covered it returns &Notdef
// and false.
func Lookup(r rune) (*Glyph, bool) {
	lo, hi := 0, len(Glyphs)
	for lo < hi {
		mid := int(uint(lo+hi) >> 1)
		if Glyphs[mid].Rune < r {
			lo = mid + 1
		} else {
			hi = mid
		}
	}
	if lo < len(Glyphs) && Glyphs[lo].Rune == r {
		return &Glyphs[lo], true
	}
	return &Notdef, false
}
